export async function* streamMetricPulsesLine(): AsyncGenerator<string> {
  yield* streamLinesRaw("sh", ["-c", "i=0; while [ $i -lt 12 ]; do echo pulse-$i; i=$((i+1)); sleep 0.2; done"], []);
}

